#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, capacity, rev;
};

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

int n, t, start, endNode, edgeCount;
int capacity[15][15], science[15][15], mazeStates[65][15][15];
int head[MAXN], level[MAXN], iter[MAXN];
bool visited[15][15], reachable[65][15][15][15][15];

vector<Edge> graph;

void add_edge(int u, int v, int cap) {
    graph.push_back({v, cap, (int)graph.size()});
    head[u] = (int)graph.size() - 1;
    graph.push_back({u, 0, (int)graph.size() - 1});
    head[v] = (int)graph.size() - 1;
}

bool bfs(int s, int t) {
    memset(level, -1, sizeof(level));
    level[s] = 0;
    std::queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = graph[i].rev) {
            int v = graph[i].to;
            if (graph[i].capacity > 0 && level[v] < 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[t] >= 0;
}

int dfs(int u, int t, int f) {
    if (u == t) return f;
    for (int &i = iter[u]; i != -1; i = graph[i].rev) {
        int v = graph[i].to;
        if (graph[i].capacity > 0 && level[v] == level[u] + 1) {
            int d = dfs(v, t, std::min(f, graph[i].capacity));
            if (d > 0) {
                graph[i].capacity -= d;
                graph[i ^ 1].capacity += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        for (int i = 0; i < MAXN; ++i) iter[i] = head[i];
        int f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
    return flow;
}

int get_id(int x, int y, int k) {
    return (x - 1) * n + y + k * n * n;
}

void dfs_search(int x, int y, int xx, int yy, int step) {
    visited[xx][yy] = true;
    reachable[step][x][y][xx][yy] = true;
    if (step >= t || mazeStates[step][xx][yy]) return;
    int directions[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
    for (int k = 0; k < 4; ++k) {
        int nx = xx + directions[k][0];
        int ny = yy + directions[k][1];
        if (nx <= 0 || ny <= 0 || nx > n || ny > n) continue;
        if (visited[nx][ny]) continue;
        if (mazeStates[step][nx][ny]) continue;
        dfs_search(x, y, nx, ny, step + 1);
    }
}

void initialize() {
    memset(visited, false, sizeof(visited));
    memset(head, -1, sizeof(head));
    edgeCount = 0;
    for (int time = 1; time <= t; ++time) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (mazeStates[time - 1][i][j])
                    mazeStates[time][i][j] = mazeStates[time - 1][i][j];
                else {
                    for (int k = 0; k < 4; ++k) {
                        int xx = i + (k == 0 ? 0 : (k == 2 ? 1 : -1));
                        int yy = j + (k == 1 ? 1 : (k == 3 ? -1 : 0));
                        if (xx <= 0 || yy <= 0 || xx > n || yy > n) continue;
                        if (mazeStates[time - 1][xx][yy] == 2)
                            mazeStates[time][i][j] = 2;
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (science[i][j]) {
                memset(visited, false, sizeof(visited));
                dfs_search(i, j, i, j, 0);
            }
    for (int i = 1; i <= t; ++i)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int xx = 1; xx <= n; ++xx)
                    for (int yy = 1; yy <= n; ++yy)
                        reachable[i][x][y][xx][yy] |= reachable[i - 1][x][y][xx][yy];
}

int main() {
    cin >> n >> t;
    start = MAXN - 1;
    endNode = start - 1;
    for (int i = 1; i <= n; ++i) {
        string s; cin >> s;
        for (int j = 1; j <= n; ++j) {
            if (isdigit(s[j - 1]))
                science[i][j] = s[j - 1] - '0';
            else if (s[j - 1] == 'Y')
                mazeStates[0][i][j] = 1;
            else if (s[j - 1] == 'Z')
                mazeStates[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= n; ++i) {
        string s; cin >> s;
        for (int j = 1; j <= n; ++j) {
            if (isdigit(s[j - 1]))
                capacity[i][j] = s[j - 1] - '0';
        }
    }
    initialize();
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            if (science[i][j])
                add_edge(start, get_id(i, j, 0), science[i][j]);
            if (capacity[i][j])
                add_edge(get_id(i, j, 1), endNode, capacity[i][j]);
        }
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int xx = 1; xx <= n; ++xx)
                for (int yy = 1; yy <= n; ++yy)
                    if (science[x][y] && capacity[xx][yy] && reachable[t][x][y][xx][yy])
                        add_edge(get_id(x, y, 0), get_id(xx, yy, 1), INF);
    cout << max_flow(start, endNode) << endl;
    return 0;
}
